1	"""Popup guard: keeps the page clear of noise while a browsing agent works, so its steps and context go to the data.
2	
3	Every browse() runs one guard next to its agent: a background sweep every GUARD_INTERVAL_S plus one sweep right before
4	each agent step (the agent then sees the cleaned page). A sweep finds what covers or replaces the page content (open
5	dialogs, modal / fixed overlays, consent banners, and short pages such as error pages with a retry button) and asks the
6	model once per kind of item what to do with it:
7	
8	- click: noise with a harmless button (cookie banner, survey, maintenance notice, error page "retry") -> click it;
9	- fill: an access check before the content (robot checkbox, slider, copy a displayed code) -> fill it, click continue;
10	- leave: anything an agent works with (login, search help, document viewer, data dialog, the bid wizard).
11	
12	The model's decision is cached per site and item signature (its text without digits + its buttons), shared by all
13	agents of the run: a maintenance dialog that comes back on every page of a site costs one model call per run, and every
14	other tab clears it without one. Fill decisions are not cached (a displayed code changes every time). `careful=True`
15	(the bid submitter) only allows clicks on noise without input fields: never fills, never touches a form.
16	"""
17	import os
18	import asyncio
19	import json
20	import logging
21	import re
22	from urllib.parse import urlparse
23	
24	log = logging.getLogger("guard")
25	
26	GUARD_INTERVAL_S = float(os.environ.get("SWARM_GUARD_INTERVAL_S", "4"))   # was 2 s: one sweep per agent tab
27	#   every 2 s added to the sandbox CPU load (see docs/INTEGRATION.md)
28	MAX_ACTIONS_PER_ITEM = 4        # per browse: an item that keeps coming back after this many tries is left to the agent
29	CLASSIFY_TIMEOUT_S = 45
30	EVAL_TIMEOUT_S = 10            # a page script that does not answer (page frozen by a native dialog) is given up
31	
32	# Runs in the page: () => {url, items: [{id, kind, text, buttons: [...], fields: [...]}]}. Element references stay in
33	# window.__swarmGuard for the click op. Looks into same-origin iframes and open shadow roots.
34	SCAN_JS = r"""() => {
35	  const norm = s => (s || '').replace(/[​-‍⁠﻿]/g, '').replace(/\s+/g, ' ').trim();
36	  const docs = [document];
37	  for (let i = 0; i < docs.length && i < 60; i++) {
38	    const d = docs[i];
39	    for (const f of d.querySelectorAll('iframe')) { try { if (f.contentDocument) docs.push(f.contentDocument); } catch (e) {} }
40	    for (const el of d.querySelectorAll('*')) { if (el.shadowRoot) docs.push(el.shadowRoot); }
41	  }
42	  const W = window.innerWidth || 1280, H = window.innerHeight || 800;
43	  const styleOf = el => { try { return (el.ownerDocument.defaultView || window).getComputedStyle(el); } catch (e) { return null; } };
44	  const shown = el => {
45	    const s = styleOf(el); if (!s) return false;
46	    const r = el.getBoundingClientRect();
47	    return r.width >= 40 && r.height >= 16 && s.display !== 'none' && s.visibility !== 'hidden' && parseFloat(s.opacity || '1') > 0.05;
48	  };
49	  const ours = el => /^(browser-use|playwright)/i.test(el.id || '') || /browser-use|playwright-highlight/i.test(el.className || '');
50	  const cands = [];
51	  for (const d of docs) {
52	    for (const el of d.querySelectorAll('*')) {
53	      if (ours(el)) continue;
54	      const role = (el.getAttribute('role') || '').toLowerCase();
55	      let dialog = (el.tagName === 'DIALOG' && el.open) || role === 'dialog' || role === 'alertdialog' || el.getAttribute('aria-modal') === 'true';
56	      let overlay = false;
57	      if (!dialog) {
58	        const s = styleOf(el);
59	        if (!s || (s.position !== 'fixed' && s.position !== 'sticky')) continue;
60	        const r = el.getBoundingClientRect();
61	        const area = Math.max(0, Math.min(r.right, W) - Math.max(r.left, 0)) * Math.max(0, Math.min(r.bottom, H) - Math.max(r.top, 0));
62	        const z = parseInt(s.zIndex) || 0;
63	        const hasButton = !!el.querySelector('button, [role=button], input[type=button], input[type=submit]');
64	        overlay = area >= 0.25 * W * H || (hasButton && z >= 1 && area >= 0.03 * W * H);
65	        if (!overlay) continue;
66	      }
67	      if (!shown(el)) continue;
68	      cands.push(el);
69	    }
70	  }
71	  const outer = cands.filter(el => !cands.some(o => o !== el && o.contains(el)));
72	  const btnSel = 'button, [role=button], input[type=button], input[type=submit], a';
73	  const labelOf = b => norm(b.innerText || b.value || b.getAttribute('aria-label') || b.title || '').slice(0, 60);
74	  // a link that opens another page (other path or host): decoys in popups ("accept and continue" -> elsewhere)
75	  const away = b => {
76	    if (b.tagName !== 'A') return false;
77	    const href = b.getAttribute('href') || '';
78	    if (!href || /^(#|javascript:)/i.test(href)) return false;
79	    try { const to = new URL(href, location.href); return to.origin !== location.origin || to.pathname !== location.pathname; }
80	    catch (e) { return true; }
81	  };
82	  const fieldLabel = f => norm((f.labels && f.labels[0] && f.labels[0].innerText) || f.getAttribute('aria-label') || f.placeholder || '').slice(0, 60);
83	  const items = [], refs = [], btnRefs = [];
84	  const describe = (el, kind, textOverride) => {
85	    let buttons = [...el.querySelectorAll(btnSel)];
86	    if (el.shadowRoot) buttons = buttons.concat([...el.shadowRoot.querySelectorAll(btnSel)]);
87	    buttons = buttons.filter(b => shown(b) || b.getBoundingClientRect().width > 0).slice(0, 14);
88	    const fields = [...el.querySelectorAll('input, select, textarea')]
89	      .filter(f => f.type !== 'hidden' && (shown(f) || f.type === 'checkbox' || f.type === 'range')).slice(0, 10)
90	      .map(f => ({type: (f.type || f.tagName).toLowerCase(), name: f.name || f.id || '', label: fieldLabel(f)}));
91	    let text = textOverride !== undefined ? textOverride : norm(el.innerText || el.textContent || '');
92	    for (const c of el.querySelectorAll('canvas, [role=img][aria-label]')) text += ' [' + norm(c.getAttribute('aria-label') || c.textContent) + ']';
93	    if (text.length < 3 && !buttons.length) return;
94	    refs.push(el); btnRefs.push(buttons);
95	    items.push({id: items.length, kind, text: text.slice(0, 1200),
96	                buttons: buttons.map((b, i) => ({i, label: labelOf(b), away: away(b)})),
97	                fields});
98	  };
99	  outer.slice(0, 6).forEach(el => describe(el, 'overlay'));
100	  // inline access gates (a slider to drag to the end, mostly with a robot checkbox) that lock part of a page: described
101	  // by their controls and status only (the content they lock changes on every page); skipped once unlocked
102	  let hasInlineGate = false;
103	  for (const d of docs) {
104	    for (const r of d.querySelectorAll('input[type=range], [role=slider]')) {
105	      hasInlineGate = true;
106	      if (refs.some(o => o.contains(r))) continue;
107	      let box = r.parentElement;
108	      while (box && box.parentElement && !box.querySelector('input[type=checkbox], [role=checkbox]')) box = box.parentElement;
109	      if (!box || refs.includes(box)) continue;
110	      const checks = [...box.querySelectorAll('input[type=checkbox]')];
111	      const max = r.max !== undefined && r.max !== '' ? Number(r.max) : Number(r.getAttribute('aria-valuemax') || 100);
112	      const value = r.value !== undefined && r.value !== '' ? Number(r.value) : Number(r.getAttribute('aria-valuenow') || 0);
113	      if (value >= max && checks.every(c => c.checked)) continue;
114	      const parts = [box.getAttribute('aria-label') || ''];
115	      for (const f of box.querySelectorAll('input, [role=slider], [role=checkbox]')) if (f.type !== 'hidden') parts.push(fieldLabel(f));
116	      for (const st of box.querySelectorAll('[role=status], canvas, [role=img][aria-label]')) parts.push('[' + norm(st.getAttribute('aria-label') || st.innerText || '') + ']');
117	      const whole = norm(box.innerText || '');
118	      describe(box, 'gate', whole.length < 500 ? undefined : norm(parts.filter(Boolean).join(' | ')));
119	    }
120	  }
121	  if (!items.length && !hasInlineGate && document.body) {
122	    // a short page (error page with a retry link, notice page): its whole text, shadow roots included, is short
123	    let size = (document.body.innerText || '').length;
124	    for (const d of docs.slice(1)) size += ((d.host ? d : d.body || d).textContent || '').length;
125	    const text = norm(document.body.innerText || '');
126	    const hasPassword = docs.some(d => d.querySelector('input[type=password]'));
127	    if (text.length > 0 && size < 900 && !hasPassword && document.body.querySelector(btnSel)) describe(document.body, 'page');
128	  }
129	  window.__swarmGuard = {refs, btnRefs};
130	  return {url: location.href, items};
131	}"""
132	
133	# Runs in the page: ({id, button}) => "clicked" | "gone" | "link". Never follows a link to another page.
134	CLICK_JS = r"""(a) => {
135	  const g = window.__swarmGuard;
136	  const b = g && g.btnRefs[a.id] && g.btnRefs[a.id][a.button];
137	  if (!b || !b.isConnected) return 'gone';
138	  if (b.tagName === 'A') {
139	    const href = b.getAttribute('href') || '';
140	    if (href && !/^(#|javascript:)/i.test(href)) {
141	      const to = new URL(href, location.href);
142	      if (to.origin !== location.origin || (to.pathname !== location.pathname && !a.allow_navigation)) return 'link';
143	    }
144	  }
145	  b.click();
146	  return 'clicked';
147	}"""
148	
149	SYSTEM = """Keep web pages clear for data-collecting agents. For each item (dialog, overlay, banner, short page) decide:
150	- "click": blocking noise: cookie/consent banner (accept necessary/all button, never settings link), survey, newsletter,
151	  chat/ad popup (x/close/"no thanks"), maintenance/system notice needing only acknowledgement (prefer x/close: "accept
152	  and continue" links often go to another page and lose work), download/info bars (x), transient error page with
153	  retry button/link (retry).
154	- "fill": access check before content: robot checkbox, slider to end, displayed code/number to copy, acknowledgement
155	  checkbox. fields [{"field": label or name, "value": ...}]: checkbox "true", slider "max", code copied exactly from
156	  item text; then_click = text of confirm/continue button.
157	- "leave": all that agents work with or decide: login, search forms + search help, result lists, records, document
158	  viewers, forms asking purpose/choice, registration/interest forms, bid/offer/signing/TAN/submit/confirm/send/delete
159	  dialogs, navigation, headers, menus.
160	Never pick button marked "away": true (link to other page; decoy) unless retry of error page. Unsure -> "leave".
161	Reply JSON: {"items": [{"id": 0, "kind": "cookie|survey|notice|banner|error|gate|content|other", "action": "click|fill|leave",
162	"button": <button index for click>, "fields": [], "then_click": ""}]}"""
163	
164	_DECISIONS: dict[tuple[str, str], dict] = {}     # (site host, item signature) -> cached click/leave decision
165	_PENDING: dict[tuple[str, str], bool] = {}         # item kinds the model is classifying right now
166	_TASKS: set = set()
167	
168	
169	def signature(item: dict) -> str:
170	    """Item identity across pages and tabs: its text without digits (codes, dates, counters change) and its buttons."""
171	    text = re.sub(r"\d+", "#", item.get("text", "").lower())
172	    text = re.sub(r"\s+", " ", text)[:1200]
173	    buttons = "|".join(re.sub(r"\d+", "#", b.get("label", "").lower()) + str(bool(b.get("away"))) for b in item.get("buttons") or [])
174	    return f"{item.get('kind')}:{text}:{buttons}:{len(item.get('fields') or [])}"
175	
176	
177	def cacheable_fill(decision: dict) -> bool:
178	    """A fill that only ticks boxes and moves sliders is the same every time (cache it); one that copies a displayed
179	    code is not."""
180	    values = [str(f.get("value", "")).strip().lower() for f in decision.get("fields") or [] if isinstance(f, dict)]
181	    return bool(values) and all(v in ("true", "false", "max", "100") for v in values)
182	
183	
184	def host(url: str) -> str:
185	    return urlparse(url or "").netloc
186	
187	
188	NOISE = ("cookie", "survey", "notice", "banner", "error")
189	
190	
191	def pick_button(decision: dict, item: dict) -> int | None:
192	    """The button to click: the model's choice, unless it is a link to another page (a decoy) and the item has exactly
193	    one other button that stays on the page (its x/close): then that one. Retry links of error pages may lead away."""
194	    index = decision.get("button")
195	    buttons = item.get("buttons") or []
196	    if not isinstance(index, int) or not 0 <= index < len(buttons):
197	        return None
198	    if buttons[index].get("away") and decision.get("kind") != "error":
199	        stay = [b["i"] for b in buttons if not b.get("away")]
200	        return stay[0] if len(stay) == 1 else None
201	    return index
202	
203	
204	def safe_then_click(decision: dict, item: dict) -> str:
205	    """The confirm button to press after filling a gate, unless it leads to another page. A sandbox run: after passing
206	    the mail gate the guard pressed 'Original öffnen' (a link away, to a decoy page) on every sweep and the TAN lookup
207	    kept landing there; navigating is the agent's decision."""
208	    label = " ".join(str(decision.get("then_click") or "").split()).casefold()
209	    if not label:
210	        return ""
211	    for button in item.get("buttons") or []:
212	        if " ".join(str(button.get("label") or "").split()).casefold() == label and button.get("away"):
213	            return ""
214	    return str(decision.get("then_click"))
215	
216	
217	def allowed(decision: dict, item: dict, careful: bool) -> bool:
218	    """What the guard may do with `item`: in careful mode only clicks on noise that has no input fields."""
219	    action = decision.get("action")
220	    if action == "click":
221	        if pick_button(decision, item) is None:
222	            return False
223	        return not careful or (decision.get("kind") in NOISE and not item.get("fields"))
224	    if action == "fill":
225	        return not careful and bool(decision.get("fields") or decision.get("then_click"))
226	    return False
227	
228	
229	class PopupGuard:
230	    """One per browse(): `sweep(evaluate)` clears the page once; `loop(evaluate)` sweeps until cancelled.
231	    `evaluate(js, *args)` runs a JS arrow function in the agent's current page."""
232	
233	    def __init__(self, ctx, author: str, careful: bool = False, fill=None):
234	        """`fill(pairs, then_click, item_id)` sets fields inside the observed gate only."""
235	        self.ctx, self.author, self.careful = ctx, author, careful
236	        self._fill = fill
237	        self._fresh: dict = {}             # decisions that are not cached (fills copying a code): used once
238	        self._lock = asyncio.Lock()
239	        self._tries: dict[str, int] = {}
240	        self.actions = 0
241	
242	    async def fill(self, evaluate, pairs: list[tuple[str, str]], then_click: str, item_id: int) -> str:
243	        if self._fill is not None:
244	            return await self._fill(pairs, then_click, item_id)
245	        from swarm.forms import fill_fields, scoped_evaluator
246	        return await fill_fields(scoped_evaluator(evaluate, item_id), pairs, "", then_click)
