async def _triage(self, unknown: list[tuple]) -> dict[int, dict]:
    """Clef's decisions for the items it is sure about ({} without Clef)."""
    from swarm import decide
    if not decide.available():
        return {}

    async def one(item):
        body, buttons = clef_question(item)
        try:
            answers = await asyncio.wait_for(decide.decide(body["state"], body["questions"], retries=0),
                                             CLEF_TIMEOUT_S)
        except Exception as error:          # Clef down / slow: Qwen decides this item
            log.debug("guard clef triage failed: %s", error)
            return None
        return clef_decision(answers, buttons)
