# Clef triage (one cheap decision call per item, in parallel): what the item is, and which button clears it. Clicks on
# noise and "leave" need no text answer, so Clef settles them; access gates (field values to copy) and anything Clef is
# unsure about go to Qwen with SYSTEM above.
CLEF_KINDS = {
    "cookie": "cookie or consent banner / wall",
    "survey": "survey, newsletter, chat or advertising popup",
    "notice": "maintenance or system notice that only needs acknowledging",
    "banner": "download or info bar",
    "error": "transient error page offering a retry",
    "gate": "access check before the content: robot checkbox, slider, code to copy, acknowledgement checkbox",
    "content": "something agents work with: login, search, results, record, document viewer, form asking purpose or "
               "choice, bid/offer/signing/TAN/submit/confirm/delete dialog, navigation, menu",
}
CLEF_KIND_MIN, CLEF_BUTTON_MIN, CLEF_TIMEOUT_S = 0.75, 0.6, 20
MAX_CLEF_BUTTONS = 9


def clef_question(item: dict) -> tuple[dict, dict[str, int]]:
    """Clef state + questions for one item, and the option key -> button index map."""
    buttons = {f"b{b['i']}": b["i"] for b in (item.get("buttons") or [])[:MAX_CLEF_BUTTONS]}
    labels = {f"b{b['i']}": (b.get("label") or "(no label)") + (" [link to another page]" if b.get("away") else "")
              for b in (item.get("buttons") or [])[:MAX_CLEF_BUTTONS]}
    questions = {"kind": {"type": "choice", "criteria": CLEF_KINDS,
                          "instructions": "A data-collecting agent's web page shows this item. What is it? Unsure -> content."}}
    if labels:
        questions["button"] = {"type": "choice", "criteria": labels | {"none": "no harmless button"},
                               "instructions": "Which button clears this item without leaving the page or deciding "
                                               "anything: x/close, 'no thanks', accept (necessary) cookies, acknowledge, "
                                               "retry on an error page. Never a settings link."}
    state = {k: item.get(k) for k in ("kind", "text", "fields")}
    return {"state": state, "questions": questions}, buttons


def clef_decision(answers: dict, buttons: dict[str, int]) -> dict | None:
    """A guard decision from Clef's answers, or None when Qwen must decide (gate, or not sure enough)."""
    from swarm.decide import picked
    kind, p = picked(answers.get("kind"))
    if kind not in CLEF_KINDS or p < CLEF_KIND_MIN or kind == "gate":
        return None
    if kind == "content":
        return {"action": "leave", "kind": "content", "by": "clef"}
    button, q = picked(answers.get("button"))
    if button not in buttons or q < CLEF_BUTTON_MIN:
        return None
    return {"action": "click", "kind": kind, "button": buttons[button], "by": "clef"}


