class GuardedTools(Tools):
    """Tools whose page actions first let the popup guard clear the page. If the guard had to handle something (a
    popup, notice, error page or access gate appeared after the model looked at the page), the action is not executed:
    the model planned it on a page that no longer exists, and it must never interact with the block itself. It gets a
    short note and plans again on the cleared page; its memory is untouched."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.before_action = None       # async (action name) -> str | None: a note when the action must not run
        self.acting = False

    async def act(self, action, browser_session, *args, **kwargs):
        name = next(iter(action.model_dump(exclude_unset=True)), "")
        if self.before_action is not None and name not in PAGE_FREE_ACTIONS:
            note = await self.before_action(name)
            if note:
                return ActionResult(extracted_content=note, long_term_memory=note)
        self.acting = True
        try:
            return await super().act(action, browser_session, *args, **kwargs)
        finally:
            self.acting = False


def build_tools(ctx, site_id: str, author: str, emit, dedupe_reads: bool = True, stop_on_record: str = "") -> Tools:
    """Our actions for the browsing model: record, read_page, fill_form, share_tip. `emit(rec)` receives records and
    pages."""
    tools = GuardedTools(exclude_actions=list(EXCLUDED_ACTIONS))

