WATCH_JS = r"""() => {
  const w = window;
  if (w.__swarmWatch) return {seq: w.__swarmWatch.seq, fresh: false};
  const state = w.__swarmWatch = {seq: 1};
  const BLOCK = 'dialog,[role=dialog],[role=alertdialog],[aria-modal=true],input[type=range],[role=slider],iframe';
  const W = () => w.innerWidth || 1280, H = () => w.innerHeight || 800;
  const blocking = el => {
    if (!el || el.nodeType !== 1 || /^(browser-use|playwright)/i.test(el.id || '')) return false;
    if (el.matches && (el.matches(BLOCK) || el.querySelector && el.querySelector(BLOCK))) return true;
    let s; try { s = getComputedStyle(el); } catch (e) { return false; }
    if (s.position !== 'fixed' && s.position !== 'sticky') return false;
    const r = el.getBoundingClientRect();
    return r.width * r.height >= 0.03 * W() * H() && s.display !== 'none' && s.visibility !== 'hidden';
  };
  const obs = new MutationObserver(list => {
    for (const m of list) {
      if (m.type === 'attributes' ? blocking(m.target) : [...m.addedNodes].slice(0, 40).some(blocking)) {
        state.seq++; return;
      }
    }
  });
  obs.observe(document.documentElement, {subtree: true, childList: true, attributes: true,
                                         attributeFilter: ['class', 'style', 'open', 'hidden', 'aria-hidden']});
  return {seq: 1, fresh: true};
}"""

